import{bV as e,aL as o,u as r,G as t}from"./chunks/framework.BfzMay2U.js";const g=JSON.parse('{"title":"制造业 PHP 面试题：MySQL、并发与报表（26—50）","description":"","frontmatter":{"title":"制造业 PHP 面试题：MySQL、并发与报表（26—50）","date":"2026-11-15T10:10:00.000Z","categories":["面试","PHP"],"tags":["MySQL","索引","事务","库存","报表"],"sidebarSort":2},"headers":[],"relativePath":"php/jd/mysql-concurrency-interview.md","filePath":"php/jd/mysql-concurrency-interview.md"}'),n={name:"php/jd/mysql-concurrency-interview.md"};function s(i,a,l,d,h,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="制造业-php-面试题-mysql、并发与报表-26—50" tabindex="-1">制造业 PHP 面试题：MySQL、并发与报表（26—50） <a class="header-anchor" href="#制造业-php-面试题-mysql、并发与报表-26—50" aria-label="Permalink to &quot;制造业 PHP 面试题：MySQL、并发与报表（26—50）&quot;">​</a></h1><p>本篇围绕生产报工、批次库存和统计报表展开。回答 SQL 问题时，应把查询模式、约束、并发风险和验证方式一起说明。</p><div class="info custom-block"><p class="custom-block-title">版本边界</p><p>以下主要讨论 MySQL InnoDB。执行计划、在线 DDL、检查约束和索引优化能力随版本不同；例如 <code>EXPLAIN ANALYZE</code> 需要 MySQL 8.0.18 及以上，并会实际执行查询。</p></div><h2 id="一、建模与索引" tabindex="-1">一、建模与索引 <a class="header-anchor" href="#一、建模与索引" aria-label="Permalink to &quot;一、建模与索引&quot;">​</a></h2><h3 id="_26-工单、批次和报工应该放在一张表吗" tabindex="-1">26. 工单、批次和报工应该放在一张表吗？ <a class="header-anchor" href="#_26-工单、批次和报工应该放在一张表吗" aria-label="Permalink to &quot;26. 工单、批次和报工应该放在一张表吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不应把不同粒度的数据混在一行。工单描述生产任务，批次描述可追溯的物料或产品集合，报工描述某次工序执行事实，消耗明细描述投入批次和数量。按实体分表并用明确关系关联，必要的汇总字段作为派生数据维护。</p><p><strong>追问要点：</strong> 同一报工可能消耗多个物料批次，一张表反复增加“物料 1、物料 2”字段会破坏扩展性。批次拆分合并还需要独立的关系表。</p><h3 id="_27-自增-id、业务单号和幂等键分别有什么作用" tabindex="-1">27. 自增 ID、业务单号和幂等键分别有什么作用？ <a class="header-anchor" href="#_27-自增-id、业务单号和幂等键分别有什么作用" aria-label="Permalink to &quot;27. 自增 ID、业务单号和幂等键分别有什么作用？&quot;">​</a></h3><p><strong>参考回答：</strong> 自增 ID 适合内部关联，业务单号用于人员沟通和跨系统对账，幂等键标识同一次业务请求。三者可以不同；业务单号不必含有所有业务含义，幂等键也不能每次重试重新生成。</p><p><strong>追问要点：</strong> 唯一性范围要明确，例如 <code>(source_system, source_no)</code>，或包含工厂维度。禁止用 <code>MAX(id) + 1</code> 或当前秒数直接生成并发业务流水号。</p><h3 id="_28-为什么数量、金额和测量值不能随便用-float" tabindex="-1">28. 为什么数量、金额和测量值不能随便用 <code>FLOAT</code>？ <a class="header-anchor" href="#_28-为什么数量、金额和测量值不能随便用-float" aria-label="Permalink to &quot;28. 为什么数量、金额和测量值不能随便用 `FLOAT`？&quot;">​</a></h3><p><strong>参考回答：</strong> 二进制浮点数不能精确表示所有十进制小数，累计扣料或金额计算容易产生误差。固定精度数据通常用 <code>DECIMAL</code>，整数计件可用整数；测量原始值还应保留单位、仪器精度和原始表示。精度与舍入规则由业务确定。</p><p><strong>追问要点：</strong> PHP 中也不能把所有 <code>DECIMAL</code> 字符串强转成 float 计算，可按范围使用最小单位整数或项目已有的十进制计算能力，并明确单位换算和舍入位置。</p><h3 id="_29-联合索引如何按实际查询设计" tabindex="-1">29. 联合索引如何按实际查询设计？ <a class="header-anchor" href="#_29-联合索引如何按实际查询设计" aria-label="Permalink to &quot;29. 联合索引如何按实际查询设计？&quot;">​</a></h3><p><strong>参考回答：</strong> 先列高频过滤、关联、排序和分页条件，再结合数据分布设计。例如按工厂、状态、时间和主键查询工单，可评估 <code>(factory_id, status, created_at, id)</code>，随后用执行计划和实际耗时验证，不能仅靠“区分度最高放前面”决定。</p><p><strong>追问要点：</strong> 如果查询不按状态过滤，时间排序可能需要另一种索引。一个很长的联合索引无法覆盖所有访问模式，还会增加写入和存储成本。</p><h3 id="_30-联合索引遇到范围查询-后面的列全部失效-正确吗" tabindex="-1">30. “联合索引遇到范围查询，后面的列全部失效”正确吗？ <a class="header-anchor" href="#_30-联合索引遇到范围查询-后面的列全部失效-正确吗" aria-label="Permalink to &quot;30. “联合索引遇到范围查询，后面的列全部失效”正确吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 这种说法过于绝对。范围条件通常限制后续列继续缩小连续索引扫描区间的能力，但后续列仍可能用于索引条件下推、覆盖查询或部分排序处理。实际使用情况还取决于谓词形式、优化器和版本。</p><p><strong>追问要点：</strong> 同样不能说缺少最左列就绝不扫描该索引；可能发生全索引扫描或满足条件的跳跃扫描。应区分“使用索引”与“有效缩小扫描量”。</p><h3 id="_31-覆盖索引和回表是什么" tabindex="-1">31. 覆盖索引和回表是什么？ <a class="header-anchor" href="#_31-覆盖索引和回表是什么" aria-label="Permalink to &quot;31. 覆盖索引和回表是什么？&quot;">​</a></h3><p><strong>参考回答：</strong> InnoDB 的二级索引记录包含主键，通过主键到聚簇索引取其他列是常说的回表。查询所需列已能从索引取得时，可减少回表。例如工单列表只返回编号、时间和状态，往往比 <code>SELECT *</code> 更容易优化。</p><p><strong>追问要点：</strong> 不能为了覆盖一个低频查询把大文本放进索引。覆盖索引也不意味着扫描行数一定少，应继续检查过滤选择性。</p><h3 id="_32-explain-应重点看哪些信息" tabindex="-1">32. <code>EXPLAIN</code> 应重点看哪些信息？ <a class="header-anchor" href="#_32-explain-应重点看哪些信息" aria-label="Permalink to &quot;32. `EXPLAIN` 应重点看哪些信息？&quot;">​</a></h3><p><strong>参考回答：</strong> 看表的访问顺序、访问方式、实际选择的索引、估算扫描行数、过滤比例、临时表和排序，再结合 SQL 业务语义判断。<code>rows</code> 是估算值，实际统计应通过可用的分析工具和运行指标验证。</p><p><strong>追问要点：</strong> <code>Using index</code> 与 <code>Using index condition</code> 含义不同，<code>Using filesort</code> 也不等于一定使用磁盘排序。生产上使用会执行查询的分析工具前，必须评估负载和执行成本。</p><h3 id="_33-为什么生产日报突然变慢-你会按什么顺序排查" tabindex="-1">33. 为什么生产日报突然变慢？你会按什么顺序排查？ <a class="header-anchor" href="#_33-为什么生产日报突然变慢-你会按什么顺序排查" aria-label="Permalink to &quot;33. 为什么生产日报突然变慢？你会按什么顺序排查？&quot;">​</a></h3><p><strong>参考回答：</strong> 先确认数据量、查询条件、时间段和最近变更，再拆分接口耗时为 SQL、锁等待、数据传输、PHP 组装和导出。检查慢查询、执行计划、索引统计和是否出现 N+1，随后验证优化是否降低实际扫描量及整体耗时。</p><p><strong>场景追问：</strong> 不要一开始就加缓存。若报表出现明细关联倍增，缓存只会更快地返回错误结果。</p><h3 id="_34-深分页应该怎样优化" tabindex="-1">34. 深分页应该怎样优化？ <a class="header-anchor" href="#_34-深分页应该怎样优化" aria-label="Permalink to &quot;34. 深分页应该怎样优化？&quot;">​</a></h3><p><strong>参考回答：</strong> <code>OFFSET</code> 越大通常越需要扫描并丢弃前面的行。连续翻页或导出可使用基于稳定排序键的游标分页，例如按 <code>(created_at, id)</code> 共同排序，并记录上一页末尾两项值。排序键应能消除相同时间造成的不确定顺序。</p><p><strong>追问要点：</strong> 游标分页不天然支持任意跳到第几页；后台若确实需要随机跳页，可保留有边界的页码方案。历史数据的并发变化还需结合快照要求处理。</p><h2 id="二、事务与并发控制" tabindex="-1">二、事务与并发控制 <a class="header-anchor" href="#二、事务与并发控制" aria-label="Permalink to &quot;二、事务与并发控制&quot;">​</a></h2><h3 id="_35-acid-在报工业务里分别体现为什么" tabindex="-1">35. ACID 在报工业务里分别体现为什么？ <a class="header-anchor" href="#_35-acid-在报工业务里分别体现为什么" aria-label="Permalink to &quot;35. ACID 在报工业务里分别体现为什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 原子性保证报工和扣料一起提交或回滚；一致性依赖约束与业务规则共同维护；隔离性控制并发操作相互影响；持久性确保成功提交的数据按数据库配置可靠保存。事务不会自动知道“已冻结批次不许扣料”这类业务规则。</p><p><strong>追问要点：</strong> 数据库原子提交不代表 ERP 同步也成功；持久性还受刷盘、存储和复制配置影响，备份与恢复是另一层保障。</p><h3 id="_36-rc-和-rr-有什么区别" tabindex="-1">36. RC 和 RR 有什么区别？ <a class="header-anchor" href="#_36-rc-和-rr-有什么区别" aria-label="Permalink to &quot;36. RC 和 RR 有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> InnoDB 的普通一致性读取在 RC 下通常每条语句建立新读视图，RR 下通常复用事务内首次一致性读建立的视图。锁定读取和更新读取当前可操作的数据，不能把所有 SQL 都理解成同一份快照。</p><p><strong>追问要点：</strong> RR 不自动消除所有业务并发问题。先查询库存再无条件更新，仍可能丢失更新；需要条件更新、锁或版本号配合业务规则。</p><h3 id="_37-两人同时扣减同一批物料-怎样避免负库存" tabindex="-1">37. 两人同时扣减同一批物料，怎样避免负库存？ <a class="header-anchor" href="#_37-两人同时扣减同一批物料-怎样避免负库存" aria-label="Permalink to &quot;37. 两人同时扣减同一批物料，怎样避免负库存？&quot;">​</a></h3><p><strong>参考回答：</strong> 简单单行扣减可使用带条件的原子更新，例如 <code>UPDATE stocks SET available_qty = available_qty - :qty WHERE id = :id AND available_qty &gt;= :qty</code>，检查影响行数。多物料与流水写入放入事务，并统一加锁顺序，任何一项不足都回滚。</p><p><strong>追问要点：</strong> <code>qty</code> 必须是校验后的正数，并校验组织、批次放行状态和单位。单纯先 <code>SELECT</code> 再 <code>UPDATE</code>，或只在前端限制数量，无法处理并发。</p><h3 id="_38-select-for-update-有哪些使用条件" tabindex="-1">38. <code>SELECT ... FOR UPDATE</code> 有哪些使用条件？ <a class="header-anchor" href="#_38-select-for-update-有哪些使用条件" aria-label="Permalink to &quot;38. `SELECT ... FOR UPDATE` 有哪些使用条件？&quot;">​</a></h3><p><strong>参考回答：</strong> 在明确的事务内查询并锁定后续要修改的数据，使用合适索引缩小扫描和锁定范围，事务尽快结束。先锁定再读取用于决策的最新状态，不能在锁外检查库存、锁内直接相信旧值。</p><p><strong>追问要点：</strong> 锁范围与索引、查询条件和隔离级别有关，不保证任何 SQL 都“只锁一行”。事务里不要调用慢速 ERP 接口或等待用户确认。</p><h3 id="_39-乐观锁与悲观锁如何选择" tabindex="-1">39. 乐观锁与悲观锁如何选择？ <a class="header-anchor" href="#_39-乐观锁与悲观锁如何选择" aria-label="Permalink to &quot;39. 乐观锁与悲观锁如何选择？&quot;">​</a></h3><p><strong>参考回答：</strong> 低冲突的编辑页面可用版本号条件更新，版本不符提示用户重新查看；库存竞争或多个关联校验可评估悲观锁。乐观锁只检测冲突，不会自动合并两个不同的业务意图。</p><p><strong>场景追问：</strong> 工艺规则编辑使用 <code>WHERE id = ? AND version = ?</code>，更新成功才递增版本并写审计；用户冲突后不能用旧表单无限重试覆盖新规则。</p><h3 id="_40-行锁、间隙锁和临键锁怎么理解" tabindex="-1">40. 行锁、间隙锁和临键锁怎么理解？ <a class="header-anchor" href="#_40-行锁、间隙锁和临键锁怎么理解" aria-label="Permalink to &quot;40. 行锁、间隙锁和临键锁怎么理解？&quot;">​</a></h3><p><strong>参考回答：</strong> 记录锁锁住索引记录，间隙锁限制向索引间隙插入，临键锁结合记录与前方间隙。InnoDB 在 RR 下部分范围锁定读取会使用这类锁控制并发插入，实际行为由查询方式和索引决定。</p><p><strong>追问要点：</strong> 唯一索引的精确命中和非唯一范围扫描可能具有不同锁范围；RC 下的间隙锁行为也不同，不能只凭隔离级别名称推断所有场景。</p><h3 id="_41-死锁如何诊断和处理" tabindex="-1">41. 死锁如何诊断和处理？ <a class="header-anchor" href="#_41-死锁如何诊断和处理" aria-label="Permalink to &quot;41. 死锁如何诊断和处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 保存死锁报告和事务 SQL，定位资源获取顺序、索引缺失和事务持续时间。通过固定更新顺序、缩小事务、补适合的索引减少死锁，对数据库已回滚的事务进行有限次数整体重试，并确保业务幂等。</p><p><strong>追问要点：</strong> 死锁不等于数据库故障；锁等待超时与死锁的回滚范围可能不同，应用应按实际配置明确回滚整个业务事务，不可在异常后继续提交部分修改。</p><h3 id="_42-幂等为什么一定要考虑数据库唯一约束" tabindex="-1">42. 幂等为什么一定要考虑数据库唯一约束？ <a class="header-anchor" href="#_42-幂等为什么一定要考虑数据库唯一约束" aria-label="Permalink to &quot;42. 幂等为什么一定要考虑数据库唯一约束？&quot;">​</a></h3><p><strong>参考回答：</strong> 并发请求可以同时通过“先查不存在”的判断，唯一约束提供最终的冲突仲裁。幂等记录与业务动作应建立原子关系，记录业务键、规范化请求摘要、状态和结果；重复请求返回原结果，同键不同内容返回冲突。</p><p><strong>追问要点：</strong> 只在唯一键报错后返回“成功”不够，还要确认原请求已经成功、内容一致且当前用户有权读取该结果。不要把其他唯一约束错误误判为幂等命中。</p><h3 id="_43-读写分离后-提交成功却查不到数据怎么处理" tabindex="-1">43. 读写分离后，提交成功却查不到数据怎么处理？ <a class="header-anchor" href="#_43-读写分离后-提交成功却查不到数据怎么处理" aria-label="Permalink to &quot;43. 读写分离后，提交成功却查不到数据怎么处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 先判断是否为复制延迟。关键的写后读、库存和放行校验应路由到主库，或使用有明确一致性保证的读取策略；非关键列表可接受并展示短暂延迟。Laravel 的粘性读取设置需按连接配置和实际生命周期验证。</p><p><strong>追问要点：</strong> 当前请求内的粘性读取不等于下一次请求、队列任务也一定读主库。主从延迟还应监控，并明确报表的数据更新时间。</p><h2 id="三、报表、变更与长期数据" tabindex="-1">三、报表、变更与长期数据 <a class="header-anchor" href="#三、报表、变更与长期数据" aria-label="Permalink to &quot;三、报表、变更与长期数据&quot;">​</a></h2><h3 id="_44-工单统计关联报工、消耗和检验表后-数量为什么翻倍" tabindex="-1">44. 工单统计关联报工、消耗和检验表后，数量为什么翻倍？ <a class="header-anchor" href="#_44-工单统计关联报工、消耗和检验表后-数量为什么翻倍" aria-label="Permalink to &quot;44. 工单统计关联报工、消耗和检验表后，数量为什么翻倍？&quot;">​</a></h3><p><strong>参考回答：</strong> 多个一对多关系直接连接，会形成明细组合乘积，导致重复累加。应先按工单或目标粒度分别汇总各明细，再关联汇总结果，或按用途拆成独立查询。不要随意用 <code>SUM(DISTINCT qty)</code> 掩盖问题，相同数值可能对应不同真实记录。</p><p><strong>追问要点：</strong> 用同一工单两次报工、三次消耗的样例验证，既检查汇总值，也检查没有任何明细时的零值语义。</p><h3 id="_45-跨夜班次的日报按哪一天统计" tabindex="-1">45. 跨夜班次的日报按哪一天统计？ <a class="header-anchor" href="#_45-跨夜班次的日报按哪一天统计" aria-label="Permalink to &quot;45. 跨夜班次的日报按哪一天统计？&quot;">​</a></h3><p><strong>参考回答：</strong> 先由业务明确班次日历、时区、开始结束时间和归属日，再将统计窗口转换成明确时间范围。常用左闭右开区间，例如本日班次开始到下一班次开始之前，避免毫秒精度和边界重复计入。</p><p><strong>追问要点：</strong> 设备事件时间、服务端接收时间可能不同，迟到补传如何重算必须约定。查询时间列时尽量使用范围过滤，避免无必要地对列套日期函数。</p><h3 id="_46-良率、达成率和-oee-有什么区别" tabindex="-1">46. 良率、达成率和 OEE 有什么区别？ <a class="header-anchor" href="#_46-良率、达成率和-oee-有什么区别" aria-label="Permalink to &quot;46. 良率、达成率和 OEE 有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 良率通常衡量合格产出与对应总产出的比例，达成率衡量实际完成与计划目标的关系，OEE 通常由可用率、性能率和质量率相乘得到。每项指标都要明确分子、分母、统计粒度和返工、报废、停机的处理规则。</p><p><strong>追问要点：</strong> 汇总多个车间不能直接平均百分比，应按正确分母重新汇总。缺少可靠的运行时间、标准节拍和质量数据时，不应声称已准确算出 OEE。</p><h3 id="_47-大数据量报表如何兼顾速度与正确性" tabindex="-1">47. 大数据量报表如何兼顾速度与正确性？ <a class="header-anchor" href="#_47-大数据量报表如何兼顾速度与正确性" aria-label="Permalink to &quot;47. 大数据量报表如何兼顾速度与正确性？&quot;">​</a></h3><p><strong>参考回答：</strong> 先优化查询和统计粒度，再按业务时效要求选择预聚合或异步生成。派生报表应记录统计口径、数据水位和生成时间，对迟到、冲销与修订数据提供重算机制；高风险放行判断不能使用可能过期的统计缓存。</p><p><strong>追问要点：</strong> 导出使用明确的快照或截止水位；仅记录最大 ID 不能阻止旧记录被更新，需要结合数据不可变规则或快照策略定义一致性。</p><h3 id="_48-给大表加字段、索引时怎样避免影响生产" tabindex="-1">48. 给大表加字段、索引时怎样避免影响生产？ <a class="header-anchor" href="#_48-给大表加字段、索引时怎样避免影响生产" aria-label="Permalink to &quot;48. 给大表加字段、索引时怎样避免影响生产？&quot;">​</a></h3><p><strong>参考回答：</strong> 先确认 MySQL 版本、表大小、执行算法、磁盘余量与锁影响，在接近真实规模的环境演练。在线 DDL 也可能等待元数据锁，并增加 IO 或复制延迟；上线前设监控、窗口、停止条件和回退方案。</p><p><strong>追问要点：</strong> 应用可用“先兼容新旧结构、再迁移数据、最后收紧约束”的方式发布。不得把“支持在线 DDL”理解为完全无阻塞、无风险。</p><h3 id="_49-生产记录为什么不能简单软删除或直接归档" tabindex="-1">49. 生产记录为什么不能简单软删除或直接归档？ <a class="header-anchor" href="#_49-生产记录为什么不能简单软删除或直接归档" aria-label="Permalink to &quot;49. 生产记录为什么不能简单软删除或直接归档？&quot;">​</a></h3><p><strong>参考回答：</strong> 软删除改变默认查询可见性，可能让批次追溯、对账或报表遗漏历史。关键记录应使用明确的作废、冲销和版本规则，保留原始关联及原因；归档需要保持可检索、可恢复和权限控制，并遵守已确认的保留要求。</p><p><strong>追问要点：</strong> 唯一键与软删除的组合要实际验证。MySQL 唯一索引允许多个 <code>NULL</code>，因此 <code>(business_no, deleted_at)</code> 不一定能阻止多条未删除的重复单号。</p><h3 id="_50-如何验证备份真正有用" tabindex="-1">50. 如何验证备份真正有用？ <a class="header-anchor" href="#_50-如何验证备份真正有用" aria-label="Permalink to &quot;50. 如何验证备份真正有用？&quot;">​</a></h3><p><strong>参考回答：</strong> 在隔离环境执行恢复演练，验证完整备份、所需日志和恢复步骤能达到约定 RPO、RTO。检查业务记录数量、关键约束、附件、审计和外部系统的对账情况，记录实际恢复耗时与丢失范围。</p><p><strong>追问要点：</strong> 主从复制会复制误删，不能代替备份；数据库回到过去不意味着 ERP 也回滚，恢复后应按业务键做差异识别和受控补偿。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./laravel-php-interview.html">上一篇：Laravel 与后端开发（01—25）</a></li><li><a href="./integration-device-interview.html">下一篇：系统集成与设备联网（51—75）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/innodb-transaction-model.html" target="_blank" rel="noreferrer">MySQL InnoDB 事务模型</a></li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/explain.html" target="_blank" rel="noreferrer">MySQL EXPLAIN</a></li></ul>',83)])])}const _=e(n,[["render",s]]);export{g as __pageData,_ as default};
